Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
Ltac accok_fp_on ::= fail.

(* [comment removed for export] *)
Ltac lres_tac2 :=
  unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end;
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  unfold pix_new_live, RASTER_COST, RC1 in *; cbn [length app]; unfold FRAMES_MAX, LIVE_MAX in *;
  split; [lia|]; split; [lia|]; split; [lia|];
  let p := fresh "p" in let n := fresh "n" in let Hn := fresh "Hn" in intros p n Hn; cbn [In] in Hn;
  repeat (destruct Hn as [Hn|Hn]; [injection Hn as <- <-; first [clear; lia | unfold rsize; lia] |]);
  lazymatch goal with L : forall q k, In (q, k) _ -> 0 < k |- _ => exact (L _ _ Hn) end.

(* [comment removed for export] *)
Ltac lres_tac4 :=
  unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end;
  repeat match goal with H : rt_live _ _ = rt_live _ _ |- _ => rewrite H end;
  cbn [length]; unfold FRAMES_MAX, LIVE_MAX, RASTER_COST, RC1 in *;
  split; [lazymatch goal with FB : Z.of_nat (length (rt_frames _ ?S0)) + _ <= 256 |- _ => clear - FB; lia | |- _ => lia end|];
  split; [lazymatch goal with L4 : Z.of_nat (length (rt_live _ ?S4)) <= _, LB : Z.of_nat (length (rt_live _ ?S0)) + _ <= _ |- _ => clear - L4 LB; lia end|];
  split; [repeat match goal with H : context [rt_credit] |- _ => revert H end; clear; intros; lia|];
  lazymatch goal with L : forall q k, In (q, k) (rt_live _ ?S4) -> 0 < k |- forall p n, In (p, n) (rt_live _ ?S5) -> 0 < n =>
    first [exact L | intros p n Hn; apply (L p n); revert Hn; repeat match goal with H : rt_live _ _ = rt_live _ _ |- _ => rewrite H end; intros Hn; exact Hn] end.

(* [comment removed for export] *)
Ltac kcm_step KCM mb segtac :=
  lazymatch type of KCM with ?c <> 0 -> keeps_live ?L ?m4 ?ma =>
    let K := fresh "KCM" in
    assert (K : c <> 0 -> keeps_live L m4 mb)
      by (let NZ := fresh "NZ" in intros NZ; apply (keeps_live_trans L m4 ma mb (KCM NZ)); segtac NZ);
    clear KCM; rename K into KCM end.
(* [comment removed for export] *)
Ltac kall_seg RT AF Sg fr LOW LOR name :=
  lazymatch goal with MUx : munch _ ?ma ?mb, Ax : ART RT ?S4 ?ma |- _ =>
    let FRS4 := fresh "FRS4" in
    assert (FRS4 : rt_frames RT S4 = (fr, 1%nat) :: rt_frames RT Sg) by (repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; reflexivity);
    assert (name : keeps_live (rt_live RT S4) ma mb)
      by (let bb := fresh "bb" in let kk := fresh "kk" in let Hin := fresh "Hin" in let aa := fresh "aa" in let Haa := fresh "Haa" in
          intros bb kk Hin aa Haa; apply MUx;
          pose proof (af_live_range RT AF S4 ma bb kk Ax Hin) as (LR0 & LR1 & LR2);
          pose proof (af_frames_range RT AF S4 ma fr 1%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (_ & _ & _ & D1); specialize (D1 bb kk Hin);
          pose proof (af_fshadow_apart RT AF S4 ma fr 1%nat Ax ltac:(rewrite FRS4; left; reflexivity)) as (D2 & _); specialize (D2 bb kk Hin);
          change (fs_size 1%nat) with 128 in D1, D2; unfold shad, SHB in D2;
          repeat match goal with H : rt_sp0 RT _ = _ |- _ => rewrite H in LR1 end; unfold STACK_WIN, USTACK_TOP, RT_STACK, SEGTOP_A in LR1, LR2;
          cbn [outside]; clear - LR0 LR1 LR2 D1 D2 Haa LOW LOR; repeat split; try exact I; first [lia | Z.div_mod_to_equations; lia]);
    clear FRS4
  end.

(* [comment removed for export] *)
Ltac idx_at_off off l :=
  lazymatch off with
  | Z0 => constr:(O)
  | _ => lazymatch l with ?c :: ?l' => let off' := eval lazy in (off - Z.of_nat (csize c))%Z in let n := idx_at_off off' l' in constr:(S n) end
  end.
Ltac cell_at H off NAME :=
  lazymatch type of H with rw_cells _ _ _ ?cs =>
    let k := idx_at_off off cs in
    let T := fresh "T" in let T3 := fresh "T3" in
    pose proof H as T; split_at T k NAME; split_at NAME 1%nat T3; clear T T3 end.

Definition R90_STOPS : list Z := [e_stack_malloc 1%nat; e_pixCreate; e_pixCopyColormap; e_pixCopyResolution_po; e_pixCopyInputFormat; e_pixCopySpp;
                                 r90_cw; r90_ccw; r90_dn; r90_fl].

Section ROT90C.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis CRE1 : pixCreate1_sure_cps RT.
Hypothesis PCC : pixCopyColormap_cpsF RT.
Hypothesis CPR : pixCopyResolution_po_cps RT.
Hypothesis CIF : pixCopyInputFormat_cps RT.
Hypothesis CSP : pixCopySpp_cps RT.
Hypothesis LIVE_LO : art_live_lo RT.

Lemma rot90_ccw0 : pixRotate90_dcase RT 0 (-1).
Proof using AF GP FKC CRE1 PCC CPR CIF CSP LIVE_LO.
ltac2:(KReplay.run1 (kr_t_Po_rot90_ccw0 ()) ["ROT90C"] (String.concat "" [kr_b_Po_rot90_ccw0_1_1 (); kr_b_Po_rot90_ccw0_1_2 ()])). Qed.
End ROT90C.
